add_filter( 'woocommerce_debug_tools', 'perfectpixel_failed_actions_tool' );

function perfectpixel_failed_actions_tool( $tools ) {
	$tools['perfectpixel_delete_failed_actions'] = array(
		'name'     => 'Διαγραφή αποτυχημένων προγραμματισμένων ενεργειών',
		'button'   => 'Διαγραφή',
		'desc'     => 'Σβήνει όλες τις εργασίες του Action Scheduler με κατάσταση «failed» (και τα logs τους). Οι εκκρεμείς εργασίες δεν αγγίζονται.',
		'callback' => 'perfectpixel_delete_failed_actions',
	);
	return $tools;
}

function perfectpixel_delete_failed_actions() {
	global $wpdb;
	if ( ! current_user_can( 'manage_woocommerce' ) ) {
		return 'Δεν έχετε δικαίωμα.';
	}
	$actions = $wpdb->prefix . 'actionscheduler_actions';
	$logs    = $wpdb->prefix . 'actionscheduler_logs';
	$ids     = $wpdb->get_col( "SELECT action_id FROM {$actions} WHERE status = 'failed' LIMIT 50000" );
	if ( ! $ids ) {
		return 'Δεν βρέθηκαν αποτυχημένες ενέργειες.';
	}
	foreach ( array_chunk( array_map( 'intval', $ids ), 1000 ) as $chunk ) {
		$in = implode( ',', $chunk );
		$wpdb->query( "DELETE FROM {$logs} WHERE action_id IN ({$in})" );
		$wpdb->query( "DELETE FROM {$actions} WHERE action_id IN ({$in})" );
	}
	return sprintf( 'Διαγράφηκαν %d αποτυχημένες ενέργειες.', count( $ids ) );
}
